import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"Codex Base URL 怎么填","description":"Codex、CC Switch 和 OpenAI 兼容工具接入 CCWS 时，Base URL 固定填写 https://www.ccws.pro/v1。","frontmatter":{"title":"Codex Base URL 怎么填","description":"Codex、CC Switch 和 OpenAI 兼容工具接入 CCWS 时，Base URL 固定填写 https://www.ccws.pro/v1。"},"headers":[],"relativePath":"guide/codex-base-url.md","filePath":"guide/codex-base-url.md","lastUpdated":1783061751000}'),i={name:"guide/codex-base-url.md"};function s(c,e,r,l,p,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="codex-base-url-怎么填" tabindex="-1">Codex Base URL 怎么填 <a class="header-anchor" href="#codex-base-url-怎么填" aria-label="Permalink to &quot;Codex Base URL 怎么填&quot;">​</a></h1><p>如果 Codex、CC Switch 或其他工具要求填写 OpenAI 兼容的 Base URL，请固定填写：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://www.ccws.pro/v1</span></span></code></pre></div><p>这个地址用于模型接口请求。不要只填写官网根地址，也不要在 <code>/v1</code> 后面继续拼接模型路径。</p><h2 id="应该填写哪个地址" tabindex="-1">应该填写哪个地址 <a class="header-anchor" href="#应该填写哪个地址" aria-label="Permalink to &quot;应该填写哪个地址&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>填写内容</th></tr></thead><tbody><tr><td>Codex Provider 的 Base URL</td><td><code>https://www.ccws.pro/v1</code></td></tr><tr><td>CC Switch 的 API 请求地址</td><td><code>https://www.ccws.pro/v1</code></td></tr><tr><td>OpenAI 兼容工具的 Base URL</td><td><code>https://www.ccws.pro/v1</code></td></tr><tr><td>官网链接或网站地址</td><td><code>https://www.ccws.pro</code></td></tr></tbody></table><p>如果页面字段名是「官网链接」「Website」或「站点地址」，填写官网根地址。只有字段明确要求 Base URL、API 请求地址或 OpenAI 兼容地址时，才填写带 <code>/v1</code> 的地址。</p><h2 id="配置前要准备什么" tabindex="-1">配置前要准备什么 <a class="header-anchor" href="#配置前要准备什么" aria-label="Permalink to &quot;配置前要准备什么&quot;">​</a></h2><ul><li>已经完成 <a href="/guide/register">注册 / 登录</a>。</li><li>已经在 CCWS 控制台创建 API Key。</li><li>当前账号有可用额度。</li></ul><p>如果还没有创建 Key，先看 <a href="/guide/codex-api-key">Codex API Key 配置</a>。</p><h2 id="填完后怎么验证" tabindex="-1">填完后怎么验证 <a class="header-anchor" href="#填完后怎么验证" aria-label="Permalink to &quot;填完后怎么验证&quot;">​</a></h2><p>保存配置后，重新打开 Codex 或重启当前终端，再发送一个简单测试：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请用一句话介绍当前项目，不要修改文件。</span></span></code></pre></div><p>如果 Codex 能正常回复，说明 Base URL 和 API Key 已经被当前工具读取。</p><h2 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h2><ul><li>只填写 <code>https://www.ccws.pro</code>：Codex API 请求需要 <code>/v1</code>。</li><li>填成 <code>https://www.ccws.pro/v1/chat/completions</code>：Base URL 不要填写完整接口路径。</li><li>修改配置后没有重启 Codex 或终端：工具可能仍在读取旧配置。</li><li>API Key 来自其他账号或已失效：请回到控制台重新确认。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/guide/api-key">请求地址 / API Key</a></li><li><a href="/guide/codex">Codex 配置</a></li><li><a href="/guide/cc-switch-provider">CC Switch 添加 CCWS Provider</a></li><li><a href="/troubleshooting/network">网络与连接排查</a></li></ul>',18)])])}const w=t(i,[["render",s]]);export{u as __pageData,w as default};
